// Deterministic PRNG: mulberry32 (seeded with workflow execution ID)
function mulberry32(seed) {
  return function() {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  }
}
const rng = mulberry32($json._execution_seed || 12345);
const prices = $input.first().json;
const holdings = {bitcoin: 0.5, ethereum: 5};
let totalValue = 0;
const breakdown = [];
Object.entries(holdings).forEach(([asset, amount]) => {
  const price = prices[asset]?.usd || 0;
  const value = amount * price;
  totalValue += value;
  breakdown.push({asset, amount, price, value, pnl_pct: rng() * 40 - 10});
});
return [{json: {total_value: totalValue, total_pnl: {realized: 1500, unrealized: 3200, total: 4700}, asset_breakdown: breakdown, performance_metrics: {roi_30d: 12.5, sharpe: 1.8, max_drawdown: -15.2}, timestamp: new Date().toISOString()}}];
